// RTL test of the real DCache with the real gate and the controller (TESTPLAN section 5).
//   DUT   : CoreResetDCacheHarness (elab/CoreResetDCacheHarness.scala): DCacheWrapper + TLBuffer + TLQuiesceGate("l1d")
//   ctrl  : the RTL CoreResetCtrl_* module (`CTRL_MOD, from verification/rtl) or, with +define+CTRL_MODEL, the model
//           cr_ctrl (the mutants of the controller are defines of the model: CTRL_MUTANT_*)
//   L2    : rtl_l2.sv, a TL-C responder with its own counters
// Generated by the run script into the include directory: params.svh (sizes of the elaboration), dut_decl.svh /
// dut_inst.svh (ports of the DUT, scripts/dcache_ports.py), mem_probes.svh (arrays and gate, scripts/mem_probes.py).
// +CASE=<D1..D13|R> +SEED=<n>. Last line of the log: `RESULT: PASS ...` or `RESULT: FAIL ERROR <K>: ...`.
// Checks K1..K11: TESTPLAN 5.5; K9 (asserts of the RTL) is the grep of the run script over the log.

module dcache_tb import dp::*; ;
  localparam bit IS_KEEP = (KEEP != 0);
`ifdef ISO2
  localparam int ISO_CYC = 2;
`else
  localparam int ISO_CYC = 1;
`endif
  localparam int RST_CYC = 100;
  localparam int MAXCYC  = 800000;

  logic clk = 1'b0;
  always #5 clk = ~clk;
  logic rst = 1'b1;
  logic dut_reset;
  assign dut_reset = rst;
  int cycle = 0;
  always @(posedge clk) cycle <= cycle + 1;

  // ------------------------------------------------------------------ DUT
`include "dut_decl.svh"
`include "dut_inst.svh"
`include "mem_probes.svh"

  // ------------------------------------------------------------------ controller
  logic req_man = 1'b0, req_trig = 1'b0;
  wire  req = req_man | req_trig;
  logic ctl_busy, ctl_in_reset, ctl_hart, ctl_l1_req, ctl_freeze, ctl_early_block, ctl_gate_block;
  logic ctl_hold, ctl_ack, ctl_isolate, ctl_core_reset;
  logic [2:0] st_model;
`ifdef CTRL_MODEL
  cr_ctrl #(.KEEP(IS_KEEP), .RST_CYCLES(RST_CYC), .ISO_CYCLES(ISO_CYC)) ctl (
    .clk(clk), .rst(rst), .req(req), .busy(ctl_busy), .in_reset(ctl_in_reset), .hart_in_reset(ctl_hart),
    .l1_req(ctl_l1_req), .l1_freeze(ctl_freeze), .l1_done(quiesce_done), .l1_idle(quiesce_idle),
    .l1_alive(quiesce_alive), .core_in_reset(core_in_reset), .early_block(ctl_early_block),
    .gate_block(ctl_gate_block), .hold_probe(ctl_hold), .ack_probe(ctl_ack), .early_quiet(1'b1),
    .gates_quiet(gate_quiet), .isolate(ctl_isolate), .core_reset(ctl_core_reset), .st(st_model));
`else
  assign st_model = 3'd0;
  `CTRL_MOD ctl (
    .clock(clk), .reset(rst), .io_req(req), .io_busy(ctl_busy), .io_inReset(ctl_in_reset),
    .io_hartInReset(ctl_hart), .io_l1_req(ctl_l1_req), .io_l1_freeze(ctl_freeze), .io_l1_done(quiesce_done),
    .io_l1_idle(quiesce_idle), .io_l1_alive(quiesce_alive), .io_coreInReset(core_in_reset),
    .io_earlyBlock(ctl_early_block), .io_gateBlock(ctl_gate_block), .io_holdProbe(ctl_hold),
    .io_ackProbe(ctl_ack), .io_earlyQuiet(1'b1), .io_gatesQuiet(gate_quiet), .io_isolate(ctl_isolate),
    .io_coreReset(ctl_core_reset));
`endif
  assign quiesce_req    = ctl_l1_req;
  assign quiesce_freeze = ctl_freeze;
  assign gate_block     = ctl_gate_block;
  assign gate_holdB     = ctl_hold;
  assign gate_ackB      = ctl_ack;
  assign gate_isolate   = ctl_isolate;
  assign core_reset     = ctl_core_reset;

  // phase of the sequence, derived from the outputs only (codes as in the model: 0 sIdle, 1 sQuiesce, 2 sDrain,
  // 3 sIso, 4 sReset, 5 sRelease); in the model run it is compared with the state of the model
  wire [2:0] ph = !ctl_busy ? 3'd0 :
                  (ctl_l1_req && !ctl_gate_block) ? 3'd1 :
                  (ctl_l1_req && ctl_gate_block && !ctl_isolate) ? 3'd2 :
                  (ctl_l1_req && ctl_isolate) ? 3'd3 :
                  ctl_core_reset ? 3'd4 : 3'd5;
  // the core (the stand's drivers) runs outside sReset and sRelease
  wire core_alive = !(ctl_isolate && !ctl_l1_req);

  // ------------------------------------------------------------------ L2
  int k_grant_delay = 3, k_rel_delay = 3, k_cbo_delay = 3;
  logic k_c_stall = 1'b0;
  logic pr_req = 1'b0; addr_t pr_addr = '0; logic [1:0] pr_cap = 2'd2;
  logic pr_go;
  logic l2_reset_point;
  logic l2_quiet, l2_quiet_noprobe;
  int   l2_n_open_req, l2_n_open_grant, l2_n_open_rel, l2_n_open_probe;
  logic ev_acq, ev_acq_perm, ev_cbo, ev_rel_first, ev_b_fire, ev_probe_done, ev_wb, ev_wb_data_valid;
  int   ev_wb_line; logic [BW-1:0] ev_wb_data;
  int   l2_n_acq, l2_n_rel, l2_n_probe, l2_n_gate_ack, l2_n_nton_stale, l2_n_reacq_stale, l2_n_foreign_grant;
  int   l2_last_ack_param, l2_last_probe_lat, l2_last_probe_line, l2_err;
  logic [NL*2-1:0] dir_o; logic [NL-1:0] poison_o, stale_o; logic [NL*BW-1:0] mem_o;

  rtl_l2 l2m (
    .clk(clk), .rst(rst),
    .a_valid(l2_a_valid), .a_ready(l2_a_ready), .a_opcode(l2_a_bits_opcode), .a_param(l2_a_bits_param),
    .a_size(l2_a_bits_size), .a_source(l2_a_bits_source), .a_address(l2_a_bits_address),
    .b_valid(l2_b_valid), .b_ready(l2_b_ready), .b_opcode(l2_b_bits_opcode), .b_param(l2_b_bits_param),
    .b_size(l2_b_bits_size), .b_source(l2_b_bits_source), .b_address(l2_b_bits_address),
    .b_mask(l2_b_bits_mask), .b_data(l2_b_bits_data), .b_corrupt(l2_b_bits_corrupt),
    .c_valid(l2_c_valid), .c_ready(l2_c_ready), .c_opcode(l2_c_bits_opcode), .c_param(l2_c_bits_param),
    .c_size(l2_c_bits_size), .c_source(l2_c_bits_source), .c_address(l2_c_bits_address),
    .c_data(l2_c_bits_data), .c_corrupt(l2_c_bits_corrupt),
    .d_valid(l2_d_valid), .d_ready(l2_d_ready), .d_opcode(l2_d_bits_opcode), .d_param(l2_d_bits_param),
    .d_size(l2_d_bits_size), .d_source(l2_d_bits_source), .d_sink(l2_d_bits_sink), .d_denied(l2_d_bits_denied),
    .d_data(l2_d_bits_data), .d_corrupt(l2_d_bits_corrupt),
    .e_valid(l2_e_valid), .e_ready(l2_e_ready), .e_sink(l2_e_bits_sink),
    .grant_delay(k_grant_delay), .rel_delay(k_rel_delay), .cbo_delay(k_cbo_delay), .c_stall(k_c_stall),
    .full_mode(!IS_KEEP), .reset_point(l2_reset_point),
    .pr_req(pr_req), .pr_addr(pr_addr), .pr_cap(pr_cap), .pr_go(pr_go),
    .quiet(l2_quiet), .quiet_noprobe(l2_quiet_noprobe),
    .n_open_req(l2_n_open_req), .n_open_grant(l2_n_open_grant), .n_open_rel(l2_n_open_rel),
    .n_open_probe(l2_n_open_probe),
    .ev_acq(ev_acq), .ev_acq_perm(ev_acq_perm), .ev_cbo(ev_cbo), .ev_rel_first(ev_rel_first),
    .ev_b_fire(ev_b_fire), .ev_probe_done(ev_probe_done), .ev_wb(ev_wb), .ev_wb_data_valid(ev_wb_data_valid),
    .ev_wb_line(ev_wb_line), .ev_wb_data(ev_wb_data),
    .n_acq(l2_n_acq), .n_rel(l2_n_rel), .n_probe(l2_n_probe), .n_gate_ack(l2_n_gate_ack),
    .n_nton_stale(l2_n_nton_stale), .n_reacq_stale(l2_n_reacq_stale), .n_foreign_grant(l2_n_foreign_grant),
    .last_ack_param(l2_last_ack_param), .last_probe_lat(l2_last_probe_lat), .last_probe_line(l2_last_probe_line),
    .dir_o(dir_o), .poison_o(poison_o), .stale_o(stale_o), .mem_o(mem_o), .err_cnt(l2_err));

  // ------------------------------------------------------------------ results
  int err_cnt = 0;
  bit finished = 1'b0;
  task automatic fail(input string kid, input string msg);
    err_cnt++;
    $display("ERROR %s: %s [cycle %0d phase %0d]", kid, msg, cycle, ph);
  endtask

  // ------------------------------------------------------------------ state of the stand (shared with the driver tasks)
  logic [BW-1:0] gold [NL];                       // what the core wrote, byte accurate
  bit gold_ok [NL];                               // gold is defined (FULL: lost / foreign lines are not)
  bit l1dirty [NL];                               // a store / AMO completed and L2 has not seen the data back
  bit touched [NL];
  logic [1:0] snap_dir [NL];                      // directory at the reset point
  bit snap_poison [NL];
  bit snap_valid = 1'b0;
  int full_lost = 0, full_foreign = 0, full_skipped = 0;
  int sram_bnd_iso = 0, sram_mem_iso = 0;
  int inflight_st = 0, inflight_amo = 0, inflight_cmo = 0;
  int cnt_acq_perm = 0, b2b_direct = 0, ld_hits = 0, ld_misses = 0, seqs = 0;

  // ------------------------------------------------------------------ monitors
  logic [2:0] ph_q = 3'd0;
  logic iso_q = 1'b0, core_reset_q = 1'b0, done_q = 1'b0, idle_q = 1'b0, gq_q = 1'b0, req_q = 1'b0, l1req_q = 1'b0;
  logic busy_q = 1'b0;
  int iso_run = 0;
  logic [NL-1:0] stale_q = '0;
  assign l2_reset_point = ctl_core_reset && !core_reset_q;

  // loads: the request fired two edges ago is the one answered now
  logic lf1 = 1'b0, lf2 = 1'b0; addr_t la1 = '0, la2 = '0;
  int ld_resp_cnt = 0; bit ld_last_hit = 1'b0, ld_last_miss = 1'b0; logic [63:0] ld_last_data = '0;

  always @(posedge clk) begin
    ph_q <= ph; iso_q <= ctl_isolate; core_reset_q <= ctl_core_reset; done_q <= quiesce_done;
    idle_q <= quiesce_idle; gq_q <= gate_quiet && l2_quiet; req_q <= req; l1req_q <= ctl_l1_req; busy_q <= ctl_busy;
    iso_run <= ctl_isolate ? iso_run + 1 : 0;
    lf1 <= ld_req_valid && ld_req_ready; la1 <= ld_req_addr; lf2 <= lf1; la2 <= la1;
    if (!rst) begin
`ifdef CTRL_MODEL
      if (st_model != ph) fail("TB", $sformatf("phase derived from the outputs (%0d) differs from the model state (%0d)", ph, st_model));
`endif
      // ---- K1: the point of the reset: nothing open on either side, no message in transfer
      if (ph == 3'd3 && !(gate_quiet && l2_quiet))
        fail("K1", $sformatf("sIso: gate.quiet=%0b l2.quiet=%0b (acq=%0d grant=%0d rel=%0d probe=%0d)", gate_quiet, l2_quiet,
                             l2_n_open_req, l2_n_open_grant, l2_n_open_rel, l2_n_open_probe));
      if (ph == 3'd4 && ph_q == 3'd3 && !(gate_quiet && l2_quiet))
        fail("K1", "first cycle of the core reset: something is open");
      // ---- the decision cycle (the one before isolate rose): done, idle, quiet in the same cycle (P19)
      if (ctl_isolate && !iso_q && !(done_q && idle_q && gq_q))
        fail("K2", $sformatf("isolation after a decision without done=%0b idle=%0b quiet=%0b", done_q, idle_q, gq_q));
      // ---- K2: at done: the DCache has finished everything
      if (quiesce_done && !done_q) begin
        if (!l2_quiet_noprobe)
          fail("K2", $sformatf("done with L2 open: req=%0d grant=%0d rel=%0d", l2_n_open_req, l2_n_open_grant, l2_n_open_rel));
        if (inflight_st != 0 || inflight_amo != 0 || inflight_cmo != 0)
          fail("K2", $sformatf("done with a request of the core unanswered: store=%0d amo=%0d cmo=%0d", inflight_st, inflight_amo, inflight_cmo));
      end
      // ---- K3: no Release starts after done; no new Acquire either
      if (ev_rel_first && done_q && ctl_l1_req) fail("K3", "Release started after the drain reported done");
      if (ev_acq && done_q && ctl_l1_req) fail("K3", "Acquire started after the drain reported done");
      // ---- K4: from the second cycle of l1.req nothing new is accepted
      if (ctl_l1_req && l1req_q && core_alive &&
          ((st_req_valid && st_req_ready) || (amo_req_valid && amo_req_ready) || (cmo_req_valid && cmo_req_ready)))
        fail("K4", "a store / atomic / CMO was accepted while the DCache must be blocked");
      // ---- K5: KEEP: the arrays are not accessed while the core is isolated; FULL: the probes must see something
      if (ctl_isolate) begin
        if (|probe_bnd) sram_bnd_iso++;
        if (|probe_mem_tag || |probe_mem_data) sram_mem_iso++;
        if (IS_KEEP && (|probe_bnd || |probe_mem_tag || |probe_mem_data))
          fail("K5", $sformatf("KEEP: array access while isolated (boundary=%0b tag-mem=%0b data-mem=%0b)",
                               |probe_bnd, |probe_mem_tag, |probe_mem_data));
      end
      // ---- K6: nothing crosses the gate while isolated (the ProbeAck of the gate itself excepted), B and A closed when held
      if (ctl_isolate) begin
        if (l2_a_valid && l2_a_ready) fail("K6", "A beat crossed the gate while isolated");
        if (l2_e_valid) fail("K6", "E valid towards L2 while isolated");
        if (l2_c_valid && !(!IS_KEEP && ctl_ack && l2_c_bits_opcode == 3'd4 && l2_c_bits_param == 3'd5))
          fail("K6", $sformatf("C valid towards L2 while isolated, other than the ProbeAck NtoN of the gate (op %0d param %0d)",
                               l2_c_bits_opcode, l2_c_bits_param));
        if (l2_d_valid && l2_d_ready) fail("K6", "D beat taken by the core side while isolated");
        if (|probe_core_side) fail("K6", "gate offers something to the core while isolated");
      end
      if (ctl_gate_block && l2_a_valid && l2_a_ready) fail("K6", "A beat crossed the gate after sDrain started");
      // ---- K7: Probes: held while hold_probe; FULL answers in sReset / sRelease only; KEEP never answers
      if (l2_b_valid && l2_b_ready && ctl_hold) fail("K7", "Probe passed the gate while held");
      if (l2_b_valid && l2_b_ready && ctl_isolate && IS_KEEP) fail("K7", "KEEP: the gate took a Probe while isolated");
      if (l2_b_valid && l2_b_ready && ctl_isolate && !IS_KEEP && !(ph == 3'd4 || ph == 3'd5))
        fail("K7", "FULL: the gate took a Probe outside sReset / sRelease while isolated");
      if (ev_probe_done && ctl_isolate) begin
        if (IS_KEEP) fail("K7", "KEEP: a ProbeAck came while isolated (the gate must never answer)");
        else if (l2_last_ack_param != 5 || ev_wb_data_valid) fail("K7", "FULL: the answer of the gate is not ProbeAck NtoN without data");
      end
      // ---- the isolation leads the core reset by isoCycles (S9)
      if (ctl_core_reset && !core_reset_q && iso_run < ISO_CYC)
        fail("K6", $sformatf("the core reset rose after %0d cycles of isolation, %0d required", iso_run, ISO_CYC));
      // ---- busy does not drop between sequences that follow each other
      if (busy_q && !ctl_busy && !(ph_q == 3'd5 && !req_q)) fail("K6", "busy fell outside the end of sRelease");
      if (ph_q == 3'd5 && ph == 3'd1) b2b_direct++;
    end
  end

  // data of the core / L2: what comes back from L1D is what the core wrote (K10), and what the reset does to it
  always @(posedge clk) if (!rst) begin
    if (ev_wb && ev_wb_data_valid) begin
      if (gold_ok[ev_wb_line] && ev_wb_data != gold[ev_wb_line])
        fail("K10", $sformatf("line %0d: data returned by L1D differs from what the core wrote", ev_wb_line));
      l1dirty[ev_wb_line] = 1'b0;
    end
    if (ev_wb && !ev_wb_data_valid && !IS_KEEP) begin end
    // the point of the reset
    if (ctl_core_reset && !core_reset_q) begin
      snap_valid = 1'b1; seqs++;
      for (int l = 0; l < NL; l++) begin
        snap_dir[l] = dir_o[l*2 +: 2]; snap_poison[l] = poison_o[l];
        if (!IS_KEEP) begin
          if (l1dirty[l]) begin full_lost++; gold[l] = mem_o[l*BW +: BW]; l1dirty[l] = 1'b0; end
          if (poison_o[l] && dir_o[l*2 +: 2] == 2'd2) begin full_foreign++; gold_ok[l] = 1'b0; end
        end
      end
    end
    // loads answered
    if (ld_resp_valid && lf2) begin
      int l, w;
      l = line_of(la2); w = int'((64'(la2) >> 3) & 64'(BLOCK_BYTES / 8 - 1));
      ld_resp_cnt++;
      ld_last_miss = ld_resp_miss || ld_resp_replay;
      ld_last_hit = !ld_resp_miss && !ld_resp_replay;
      ld_last_data = ld_resp_data;
      if (ld_last_hit) begin
        ld_hits++;
        if (l >= 0 && gold_ok[l] && ld_resp_data != gold[l][w*64 +: 64])
          fail("K10", $sformatf("load hit of line %0d word %0d: %h, the core wrote %h", l, w, ld_resp_data, gold[l][w*64 +: 64]));
        else if (l >= 0 && !gold_ok[l]) full_skipped++;
      end else ld_misses++;
    end
    if (cnt_acq_perm >= 0 && ev_acq_perm) cnt_acq_perm++;
  end

  // ------------------------------------------------------------------ watchdog
  always @(posedge clk) if (cycle > MAXCYC && !finished) begin
    fail("TIMEOUT", $sformatf("the case did not finish in %0d cycles", MAXCYC));
    finish_case();
  end

  // ------------------------------------------------------------------ the driver, the triggers and the cases
`include "dcache_drv.sv"

  // ------------------------------------------------------------------ main
  string cname = "D1";
  int seed = 1;
  initial begin
    if (!$value$plusargs("CASE=%s", cname)) cname = "D1";
    if (!$value$plusargs("SEED=%d", seed)) seed = 1;
    rs = 32'h9E3779B9 ^ (32'(seed) * 32'd2654435761);
    init_stand();
    rst = 1'b1;
    repeat (20) @(posedge clk);
    rst <= 1'b0;
    repeat (30) @(posedge clk);
    $display("dcache_tb: CFG=%s CASE=%s SEED=%0d ISO=%0d", IS_KEEP ? "KEEP" : "FULL", cname, seed, ISO_CYC);
    run_case(cname);
    finish_case();
  end
endmodule
